struct Command {
    char op;
    int amount;
};
int main() {
    int n;
    if (!(std::cin >> n) || n < 0 || n > 20) {
        std::cout << "invalid\n";
        return 0;
    }
    std::vector<Command> commands;
    for (int i = 0; i < n; ++i) {
        Command c;
        if (!(std::cin >> c.op >> c.amount) ||
            (c.op != '+' && c.op != '-')) {
            std::cout << "invalid\n";
            return 0;
        }
        commands.push_back(c);
    }
    std::cin >> std::ws;
    if (!std::cin.eof()) {
        std::cout << "invalid\n";
        return 0;
    }
    Stock s;
    int rejected = 0;
    for (const auto &c : commands) {
        if (!(c.op == '+' ? s.receive(c.amount) : s.ship(c.amount))) {
            ++rejected;
        }
    }
    std::cout << s.quantity() << ' ' << rejected << '\n';
}
